GR, GW, GC, GP, GU = '＿＿の言葉の読み方', '＿＿の言葉を漢字で書くとき', '（　）に入れるのに最もよいもの', '＿＿に意味が最も近いもの', '次の言葉の使い方として最もよいもの'
IG = '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。'
IR = '次の文章を読んで、質問に答えなさい。答えは、1・2・3・4から最もよいものを一つ選びなさい。'
def V(sid, qs): return {'id': sid, 'title': '文字・語彙 ' + sid[-1].upper(), 'instructions': IV, 'questions': qs}
def G(sid, qs): return {'id': sid, 'title': '文法 ' + sid[-1].upper(), 'instructions': IG, 'questions': qs}
def R(sid, kind, passage, qs): return {'id': sid, 'title': kind + ' ' + sid[-1].upper(), 'instructions': IR, 'passage': passage, 'questions': qs}

