rl = [
 R('N3RLa', '内容理解（長文）', '<p>私の会社では、去年から週に二日、家で仕事をしてもいいことになった。最初は、家だと集中できないのではないかと心配していた。家には家族もいるし、テレビもある。しかし、実際にやってみると、思ったより仕事がはかどった。通勤の時間がない分、朝の時間を有効に使えるし、会議が少ないので、自分の仕事にじっくり取り組める。</p><p>一方で、困ったこともある。同僚と直接話す機会が減ったため、ちょっとした質問がしにくくなった。会社にいれば、隣の席の人にすぐ聞けることも、家ではメールやチャットで聞かなければならない。返事が来るまで待つ時間がもったいないと感じることもある。</p><p>そこで、私たちのチームでは、毎朝十分だけオンラインで集まり、その日の予定や困っていることを話すことにした。短い時間だが、お互いの様子が分かるので、仕事がしやすくなった。</p><p>家で働くか会社で働くか、どちらがいいかは仕事の内容によって違うと思う。大切なのは、それぞれのよい点を生かして、働き方を工夫することではないだろうか。</p>', [
  M('筆者が最初に心配していたことは何か。', ['家では集中できないのではないか', '通勤に時間がかかること', '会議が多すぎること', '家族が反対すること'], None, E('家だと集中できないのではないか.', 'Not being able to focus at home.')),
  M('家で仕事をしてよかった点として、本文に合うものはどれか。', ['朝の時間を有効に使える', '同僚とよく話せる', 'テレビが見られる', '質問にすぐ答えてもらえる'], None, E('朝の時間を有効に使える.', 'Can use mornings well.')),
  M('チームで毎朝集まるようにしたのはなぜか。', ['お互いの様子が分かるようにするため', '会議を増やすため', '会社に行く日を決めるため', '仕事を早く終えるため'], None, E('お互いの様子が分かる.', 'To know how everyone is doing.')),
  M('筆者の考えに最も近いものはどれか。', ['それぞれのよい点を生かして働き方を工夫することが大切だ', '家で働くほうが必ずいい', '会社で働くほうが必ずいい', '会議はなくしたほうがいい'], None, E('Paragraf terakhir.', 'Final paragraph.'))]),
 R('N3RLb', '内容理解（長文）', '<p>子どものころ、私は本を読むのが嫌いだった。字を読むのが遅く、一冊読み終わるのに何週間もかかったからだ。学校の読書の時間は、いつも早く終わればいいと思っていた。</p><p>そんな私が本を好きになったのは、中学生のとき、図書館の先生に一冊の漫画を勧められたことがきっかけだった。歴史上の人物の一生を描いたもので、絵が多く、すぐに読めた。それまで勉強として覚えていた人物が、生きた人間のように感じられ、もっと知りたいと思った。次に、同じ人物について書かれた、字の多い本を自分で探して読んだ。時間はかかったが、不思議とつらくなかった。</p><p>今、私は小学校の教師をしている。本が苦手な子どもには、まず興味のあることから始めればいいと話している。漫画でも図鑑でもかまわない。「もっと知りたい」という気持ちがあれば、子どもは自然に次の本に手を伸ばすものだ。</p>', [
  M('筆者が子どものころ本が嫌いだった理由は何か。', ['字を読むのが遅かったから', '学校に図書館がなかったから', '漫画しか読まなかったから', '先生が厳しかったから'], None, E('字を読むのが遅く.', 'Slow reader.')),
  M('筆者が本を好きになったきっかけは何か。', ['図書館の先生に勧められた漫画', '親に買ってもらった本', '学校の宿題', '歴史のテスト'], None, E('図書館の先生に一冊の漫画を勧められた.', 'A comic recommended by the librarian.')),
  M('字の多い本を読んだとき、筆者はどう感じたか。', ['時間はかかったがつらくなかった', 'すぐに読めた', 'とてもつらかった', '途中でやめた'], None, E('時間はかかったが、不思議とつらくなかった.', 'Slow but not painful.')),
  M('筆者が本の苦手な子どもに伝えていることは何か。', ['興味のあることから始めればいい', '毎日一冊読むべきだ', '漫画は読まないほうがいい', '字の多い本から読むべきだ'], None, E('まず興味のあることから.', 'Start from interests.'))]),
]
